var roots=new[]{GameObject.Find("BossGateEntrance"),GameObject.Find("Gate Environment Transition"),GameObject.Find("Test_ShrineEntranceWalls"),GameObject.Find("HeightFog_VFX"),GameObject.Find("ApproachLanterns")};var list=new System.Collections.Generic.List<object>();foreach(var root in roots)foreach(var tr in root.GetComponentsInChildren<Transform>(true)){var renderer=tr.GetComponent<Renderer>();var mesh=tr.GetComponent<MeshFilter>();if(root.name=="ApproachLanterns"&&tr.name!="ExistingStoneLantern"&&renderer==null)continue;if(root.name=="ApproachLanterns"&&list.Count>40)continue;list.Add(new {root=root.name,name=tr.name,localPosition=tr.localPosition.ToString(),position=tr.position.ToString(),rotation=tr.eulerAngles.ToString(),scale=tr.lossyScale.ToString(),mesh=mesh!=null?AssetDatabase.GetAssetPath(mesh.sharedMesh):"",min=renderer!=null?renderer.bounds.min.ToString():"",max=renderer!=null?renderer.bounds.max.ToString():"",material=renderer!=null?renderer.sharedMaterials.Select(AssetDatabase.GetAssetPath).ToArray():null,colliders=tr.GetComponents<Collider>().Select(c=>new{name=c.GetType().Name,c.enabled,min=c.bounds.min.ToString(),max=c.bounds.max.ToString()}).ToArray()});}System.IO.File.WriteAllText("Assets/Temp/MountainPassPolish~/Test_GateAndLantern.json",Newtonsoft.Json.JsonConvert.SerializeObject(list,Newtonsoft.Json.Formatting.Indented));return new{count=list.Count};
